def comps(g,val):
    seen=set(); out=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==val and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); cs=[]
                while st:
                    a,b=st.pop(); cs.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(cs)
    return out
