def solve(g):
    out=[row[:] for row in g]
    H,W=len(g),len(g[0])
    # flood-fill solid same-color rectangles: start at every cell of non-background? Use color=4 target.
    # Find largest solid rectangle of each color; if >= some size, paint 4.
    from collections import deque
    def solid_rect(i,j,c):
        h=w=0
        return (i,j)
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if seen[i][j] or g[i][j]!=8: continue
            c=g[i][j]
            q=deque([(i,j)]); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; q.append((ny,nx)); comp.append((ny,nx))
            ys=[y for y,_ in comp]; xs=[x for _,x in comp]
            h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
            if len(comp)==h*w and h>=4 and w>=4:  # threshold?
                for y,x in comp: out[y][x]=4
    return out
